letters=['A','L','K','M']
def nxt(fig):
    # each step all rays rotate 45 deg clockwise and a new ray appears at top
    return {k:v+45 for k,v in fig.items()}
f4={'M':0,'K':45,'L':90,'A':135}
f5=nxt(f4)
opts={'A':{'M':0,'K':90,'L':135,'A':180},'B':{'H':0,'M':45,'K':90,'L':135,'A':180},'C':{'M':45,'K':90,'L':135,'A':180},'D':{'M':0,'K':45,'L':90,'A':135}}
def fits(o):
    rest={k:v for k,v in o.items() if k in f5}
    new=[k for k in o if k not in f5]
    return rest==f5 and len(new)==1 and o[new[0]]==0
assert [k for k in opts if fits(opts[k])]==['B']

# pluses and triangles each increase by 1; triangles fill left side (max 3) then bottom
def fig(n):
    return {'tri_left':min(n,3),'tri_bottom':max(0,n-3),'plus':n}
f=fig(5)
opts={'A':{'tri_left':3,'tri_bottom':1,'plus':4},'B':{'tri_left':3,'tri_bottom':2,'plus':4},
'C':{'tri_left':3,'tri_bottom':2,'plus':5},'D':{'tri_left':3,'tri_bottom':1,'plus':4}}
assert fig(4)=={'tri_left':3,'tri_bottom':1,'plus':4}
assert [k for k in opts if opts[k]==f]==['C']
